 d=json.loads(P.read_text());base=[x for x in d['layers'] if int(x['id'].split('-')[1])<301];later=[x for x in d['layers'] if int(x['id'].split('-')[1])>325];assert len(base)==300;d['layers']=sorted(base+B+later,key=lambda x:int(x['id'].split('-')[1]));assert len(B)==25 and len({x['id'] for x in d['layers']})==len(d['layers']);P.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(f"Wrote answer batch 12; total reviewed layers: {len(d['layers'])}")
